*/
scwin.tx_fn_search = async function () {
    const sbmOptions = {
        id: "tx_fn_search",
        method: "post",
        action: "/srch/srch.do?method=srchPopupList",
        ref: "dma_searchReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldinf20000p.tx_fn_search" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

// 표준 API 조합으로 새로 작성한 검사 함수
/**
 * @method
 * @name scwin.appDate2
 * @author Inswave
 * @date 2026. 09. 29
 * @param startId endId months
 * @returns
 * @hidden N
*/
scwin.appDate2 = function (startId, endId, months) { try { const end = $c.date.getServerDateTime(); const start = $c.date.addMonth(end, -Number(months || 0)); const r = function (nm) { return $c.util.getComponent('cal_' + nm) || $c.util.getComponent('ipt_' + nm) || $c.util.getComponent(String(nm)); }; const s = r(String(startId)); if (s && s.setValue) { s.setValue(start); } const e2 = r(String(endId)); if (e2 && e2.setValue) { e2.setValue(end); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'fn_appDate2' }); } };

/**
 * @method
 * @name scwin.dataTb_fmt_stdCd
 * @author Inswave
 * @date 2026. 09. 29
 * @param data formattedData r c
 * @returns
